const first = $input.first();
const input = (first && first.json && typeof first.json === 'object') ? first.json : {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const directAction = String(body.action || '').trim();
if (directAction === 'cache_feed') {
  const testId = String(body.test_id || '').trim();
  const caption = String(body.caption || '').trim();
  if (!testId || !caption) {
    return [];
  }
  const store = $getWorkflowStaticData('global');
  store.feed_payloads = (store.feed_payloads && typeof store.feed_payloads === 'object') ? store.feed_payloads : {};
  store.feed_payloads[testId] = {
    test_id: testId,
    caption,
    planned_publish_time: String(body.planned_publish_time || '21:00').trim(),
    content_slot: String(body.content_slot || 'feed_2100').trim(),
    source_url: String(body.source_url || '').trim(),
    hook: String(body.hook || '').trim(),
    image_url: String(body.image_url || body.media_url || '').trim(),
    media_url: String(body.media_url || body.image_url || '').trim(),
    updated_at: new Date().toISOString(),
  };
  return [];
}

if (directAction === 'cache_reel') {
  const testId = String(body.test_id || '').trim();
  const videoUrl = String(body.video_url || body.reel_video_url || body.media_url || body.reel_url || '').trim();
  if (!testId || !/^https?:\/\//i.test(videoUrl)) {
    return [];
  }
  const store = $getWorkflowStaticData('global');
  store.reel_video_urls = (store.reel_video_urls && typeof store.reel_video_urls === 'object') ? store.reel_video_urls : {};
  store.reel_video_urls[testId] = videoUrl;
  store.reel_payloads = (store.reel_payloads && typeof store.reel_payloads === 'object') ? store.reel_payloads : {};
  store.reel_payloads[testId] = { test_id: testId, video_url: videoUrl, caption: String(body.caption || '').trim(), planned_publish_time: String(body.planned_publish_time || '').trim(), content_slot: String(body.content_slot || '').trim(), post_type: String(body.post_type || 'reel').trim(), updated_at: new Date().toISOString() };
  store.reel_video_cached_at = new Date().toISOString();
  return [];
}

if (directAction === 'cache_carousel') {
  const testId = String(body.test_id || '').trim();
  const carousel = (body.carousel && typeof body.carousel === 'object') ? body.carousel : null;
  const media = Array.isArray(carousel?.media) ? carousel.media.filter((m) => String(m?.image_url || '').trim()) : [];
  if (!testId || media.length < 2) {
    return [];
  }

  // Preserve reel URL signal if provided in cache payload path.
  const bodyReelUrlCandidates = [
    body.video_url,
    body.reel_video_url,
    body.media_url,
    body.reel_url,
    body?.reel?.video_url,
    body?.carousel?.reel_video_url,
    body?.carousel?.video_url,
  ].map((v) => String(v || '').trim()).filter(Boolean);
  const cachedReelUrl = bodyReelUrlCandidates.find((u) => /^https?:\/\//i.test(u)) || '';

  const store = $getWorkflowStaticData('global');
  store.carousel_payloads = (store.carousel_payloads && typeof store.carousel_payloads === 'object') ? store.carousel_payloads : {};
  store.carousel_payloads[testId] = {
    caption: String(carousel.caption || '').trim(),
    media: media.map((m, idx) => ({ position: Number(m.position || (idx + 1)), image_url: String(m.image_url || '').trim() })),
    reel_video_url: cachedReelUrl,
    updated_at: new Date().toISOString(),
  };
  return [];
}

const callback = (body.callback_query && typeof body.callback_query === 'object') ? body.callback_query : null;
if (!callback) {
  return [];
}

const callbackData = String(callback.data || body.callback_data || '').trim();
const [actionRaw, testIdRaw] = callbackData.split('|');
const action = String(actionRaw || '').trim();
const testId = String(testIdRaw || '').trim();

const isQueueAction = action === 'queue_feed' || action === 'queue_reel' || action === 'queue_carousel';
const isDeleteAction = action === 'delete_test' || action === 'delete';

if (isQueueAction || isDeleteAction) {
  if (!testId) {
    throw new Error('Missing test_id in queue/delete callback');
  }

  const store = $getWorkflowStaticData('global');
  store.daily_publish_queue = (store.daily_publish_queue && typeof store.daily_publish_queue === 'object') ? store.daily_publish_queue : {};
  store.daily_deleted_items = (store.daily_deleted_items && typeof store.daily_deleted_items === 'object') ? store.daily_deleted_items : {};
  store.clean_publish_guard = (store.clean_publish_guard && typeof store.clean_publish_guard === 'object') ? store.clean_publish_guard : {};

  const nowSeoul = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
  const todayKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;
  const dedupeKey = `${action}|${testId}`;
  if (store.clean_publish_guard[dedupeKey]) {
    return [];
  }
  const message = (callback.message && typeof callback.message === 'object') ? callback.message : ((body.message && typeof body.message === 'object') ? body.message : {});
  const callbackCaption = String(message.caption || message.text || '');
  const reelMap = (store.reel_video_urls && typeof store.reel_video_urls === 'object') ? store.reel_video_urls : {};
  const feedPayloads = (store.feed_payloads && typeof store.feed_payloads === 'object') ? store.feed_payloads : {};
  const feedPayload = (feedPayloads[testId] && typeof feedPayloads[testId] === 'object') ? feedPayloads[testId] : null;
  const reelPayloads = (store.reel_payloads && typeof store.reel_payloads === 'object') ? store.reel_payloads : {};
  const reelPayload = (reelPayloads[testId] && typeof reelPayloads[testId] === 'object') ? reelPayloads[testId] : null;
  const carouselMap = (store.carousel_payloads && typeof store.carousel_payloads === 'object') ? store.carousel_payloads : {};
  let carouselPayload = (carouselMap[testId] && typeof carouselMap[testId] === 'object') ? carouselMap[testId] : null;
  if (!carouselPayload || !Array.isArray(carouselPayload.media) || carouselPayload.media.length < 2) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://n8n.mykindredai.com/webhook/clean_01_generator',
        body: { action: 'resend_carousel_cache', test_id: testId },
        json: true,
        timeout: 25000,
      });
      const refreshedStore = $getWorkflowStaticData('global');
      const refreshedMap = (refreshedStore.carousel_payloads && typeof refreshedStore.carousel_payloads === 'object') ? refreshedStore.carousel_payloads : {};
      const refreshed = (refreshedMap[testId] && typeof refreshedMap[testId] === 'object') ? refreshedMap[testId] : null;
      if (refreshed && Array.isArray(refreshed.media) && refreshed.media.length >= 2) carouselPayload = refreshed;
    } catch (_e) { /* fallback failed silently */ }
  }
  const videoUrl = String(reelMap[testId] || '').trim();
  const feedImageUrl = String(feedPayload?.image_url || feedPayload?.media_url || '').trim();

  const slotMatch = callbackCaption.match(/\[(FEED|CAROUSEL)\s*\|\s*([0-9:]+)\]/i);
  const plannedTimeFromMessage = slotMatch ? String(slotMatch[2] || '').trim() : '';
  const typeFromAction = action.replace(/^queue_/, '');
  const plannedTime = plannedTimeFromMessage || String(feedPayload?.planned_publish_time || '').trim() || String(reelPayload?.planned_publish_time || '').trim() || (
    typeFromAction === 'feed' ? '21:00' :
    typeFromAction === 'carousel' ? '' :
    ''
  );

  if (isDeleteAction) {
    store.daily_deleted_items[testId] = {
      test_id: testId,
      dateKey: todayKey,
      deleted_at: new Date().toISOString(),
      callback_data: callbackData,
      status: 'deleted',
    };
    if (store.daily_publish_queue[testId]) {
      store.daily_publish_queue[testId].status = 'deleted';
      store.daily_publish_queue[testId].deleted_at = new Date().toISOString();
    }
    return [];
  }

  if (store.daily_deleted_items[testId]) {
    return [];
  }

  if (typeFromAction === 'reel' && !/^https?:\/\//i.test(videoUrl)) {
    throw new Error(`Queue reel blocked: missing cached reel video for ${testId}`);
  }

  if (typeFromAction === 'carousel') {
    const media = Array.isArray(carouselPayload?.media) ? carouselPayload.media : [];
    if (media.length < 2) {
      delete store.clean_publish_guard[dedupeKey];
      store.carousel_cache_alerts = Array.isArray(store.carousel_cache_alerts) ? store.carousel_cache_alerts : [];
      store.carousel_cache_alerts.push({ test_id: testId, alerted_at: new Date().toISOString() });
      const _chatId = String(callback?.message?.chat?.id || body?.message?.chat?.id || '').trim();
      const _tgToken = String(store.tg_bot_token || '').trim();
      if (_chatId && _tgToken) {
        try {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${_tgToken}/sendMessage`,
            body: { chat_id: _chatId, text: `⚠️ Carousel 캐시 없음\ntest_id: ${testId}\n재승인 필요` },
            json: true,
            timeout: 5000,
          });
        } catch (_e) {}
      }
      return [];
    }
  }

  store.daily_publish_queue[testId] = {
    test_id: testId,
    dateKey: todayKey,
    post_type: typeFromAction,
    route_action: action,
    status: 'queued',
    queued_at: new Date().toISOString(),
    planned_publish_time: plannedTime,
    caption: typeFromAction === 'carousel'
      ? String(carouselPayload?.caption || callbackCaption || '').trim()
      : (typeFromAction === 'reel' ? String(reelPayload?.caption || callbackCaption || '').trim() : String(feedPayload?.caption || callbackCaption || '').trim()),
    video_url: typeFromAction === 'reel' ? videoUrl : '',
    image_url: typeFromAction === 'feed' ? feedImageUrl : '',
    media_url: typeFromAction === 'feed' ? feedImageUrl : '',
    carousel: typeFromAction === 'carousel' ? {
      caption: String(carouselPayload?.caption || callbackCaption || '').trim(),
      media: Array.isArray(carouselPayload?.media) ? carouselPayload.media : [],
    } : null,
    source: 'telegram_queue_button',
  };

  store.clean_publish_guard[dedupeKey] = new Date().toISOString();
  return [];
}


const isReelApprove = action === 'approve_test' || action === 'approve' || action === 'approve_reel';
const isCarouselApprove = action === 'approve_carousel';
if (!isReelApprove && !isCarouselApprove) {
  return [];
}

if (!testId) {
  throw new Error('Missing test_id in approve callback');
}

const store = $getWorkflowStaticData('global');
store.clean_publish_guard = (store.clean_publish_guard && typeof store.clean_publish_guard === 'object') ? store.clean_publish_guard : {};
store.daily_publish_limit = Number(store.daily_publish_limit ?? 3);
store.daily_publish_success_log = Array.isArray(store.daily_publish_success_log) ? store.daily_publish_success_log : [];

const nowSeoul = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const todayKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;
store.daily_publish_success_log = store.daily_publish_success_log.slice(-300);
const todaySuccessCount = store.daily_publish_success_log.filter((r) => String(r.dateKey || '') === todayKey).length;
if (todaySuccessCount >= store.daily_publish_limit) {
  throw new Error(`DAILY_LIMIT_REACHED limit=${store.daily_publish_limit} count=${todaySuccessCount}`);
}

const dedupeKey = `${action}|${testId}`;
if (store.clean_publish_guard[dedupeKey]) {
  return [];
}
store.clean_publish_guard[dedupeKey] = new Date().toISOString();

const message = (callback.message && typeof callback.message === 'object') ? callback.message : ((body.message && typeof body.message === 'object') ? body.message : {});
const callbackCaption = String(message.caption || message.text || '');

if (isReelApprove) {
  const payloads = (store.carousel_payloads && typeof store.carousel_payloads === 'object') ? store.carousel_payloads : {};
  const payload = payloads[testId] && typeof payloads[testId] === 'object' ? payloads[testId] : null;

  const videoMap = (store.reel_video_urls && typeof store.reel_video_urls === 'object') ? store.reel_video_urls : {};
  const mappedVideoUrl = String(videoMap[testId] || '').trim();

  // Fallback order:
  // 1) staticData.global.reel_video_urls[test_id]
  // 2) callback/body payload fields
  // 3) cached carousel/static payload fields that may contain reel URL
  const callbackCandidates = [
    body.video_url,
    body.reel_video_url,
    body.media_url,
    body.reel_url,
    body?.reel?.video_url,
    body?.carousel?.reel_video_url,
    body?.carousel?.video_url,
  ].map((v) => String(v || '').trim()).filter(Boolean);

  const payloadCandidates = [
    payload?.reel_video_url,
    payload?.video_url,
    payload?.media_url,
    payload?.reel_url,
    payload?.reel?.video_url,
  ].map((v) => String(v || '').trim()).filter(Boolean);

  const callbackVideoUrl = callbackCandidates.find((u) => /^https?:\/\//i.test(u)) || '';
  const payloadVideoUrl = payloadCandidates.find((u) => /^https?:\/\//i.test(u)) || '';
  const finalVideoUrl = mappedVideoUrl || callbackVideoUrl || payloadVideoUrl;

  if (!finalVideoUrl) {
    throw new Error(`Reel asset missing for approved test_id ${testId}; publish blocked`);
  }

  if (/samplelib\.com|gtv-videos-bucket|ForBiggerJoyrides|ForBiggerEscapes/i.test(finalVideoUrl)) {
    throw new Error('Generic sample video blocked for approve flow');
  }

  return [{
    json: {
      route_action: 'approve_reel',
      callback_data: action,
      test_id: testId,
      caption: callbackCaption,
      video_url: finalVideoUrl,
      video_source: mappedVideoUrl ? 'reel_cache' : (callbackVideoUrl ? 'callback_payload' : 'carousel_payload'),
      approved_via: 'telegram_callback',
      arm_live_publish: true,
      daily_publish_limit: store.daily_publish_limit,
      daily_publish_count_today: todaySuccessCount,
      dry_run: body.dry_run === true || String(body.dry_run || '').toLowerCase() === 'true',
      test_mode: body.test_mode === true || String(body.test_mode || '').toLowerCase() === 'true',
      diagnostic: body.diagnostic === true || String(body.diagnostic || '').toLowerCase() === 'true',
    }
  }];
}

const payloads = (store.carousel_payloads && typeof store.carousel_payloads === 'object') ? store.carousel_payloads : {};
let payload = payloads[testId] && typeof payloads[testId] === 'object' ? payloads[testId] : null;
let media = Array.isArray(payload?.media) ? payload.media : [];
if (!payload || media.length < 2) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://n8n.mykindredai.com/webhook/clean_01_generator',
      body: { action: 'resend_carousel_cache', test_id: testId },
      json: true,
      timeout: 25000,
    });
    const refreshedStore2 = $getWorkflowStaticData('global');
    const refreshedMap2 = (refreshedStore2.carousel_payloads && typeof refreshedStore2.carousel_payloads === 'object') ? refreshedStore2.carousel_payloads : {};
    const refreshed2 = refreshedMap2[testId] && typeof refreshedMap2[testId] === 'object' ? refreshedMap2[testId] : null;
    if (refreshed2 && Array.isArray(refreshed2.media) && refreshed2.media.length >= 2) { payload = refreshed2; media = refreshed2.media; }
  } catch (_e2) { /* fallback failed silently */ }
}
if (!payload || media.length < 2) {
  throw new Error(`Carousel media payload missing for approved test_id ${testId} (fallback also failed)`);
}

return [{
  json: {
    route_action: 'approve_carousel',
    callback_data: action,
    test_id: testId,
    caption: String(payload.caption || callbackCaption || '').trim(),
    carousel: {
      caption: String(payload.caption || callbackCaption || '').trim(),
      media,
    },
    approved_via: 'telegram_callback',
    arm_live_publish: true,
    daily_publish_limit: store.daily_publish_limit,
    daily_publish_count_today: todaySuccessCount,
    dry_run: body.dry_run === true || String(body.dry_run || '').toLowerCase() === 'true',
    test_mode: body.test_mode === true || String(body.test_mode || '').toLowerCase() === 'true',
    diagnostic: body.diagnostic === true || String(body.diagnostic || '').toLowerCase() === 'true',
  }
}];

const j = $json || {};
const store = $getWorkflowStaticData('global');
store.daily_publish_limit = Number(store.daily_publish_limit ?? 3);
store.daily_publish_success_log = Array.isArray(store.daily_publish_success_log) ? store.daily_publish_success_log : [];
const nowSeoul = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const dateKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;
const mediaId = String(j.media_id || j.id || '').trim();
const status = String(j.publish_status || '').toLowerCase();
const success = Boolean(j.publishSuccess === true || j.publish_success === true || status === 'success' || mediaId);
if (success) {
  store.daily_publish_success_log.push({
    dateKey,
    timestamp: new Date().toISOString(),
    test_id: String(j.test_id || ''),
    route_action: String(j.route_action || ''),
    media_id: mediaId,
    executionId: String($execution.id || ''),
  });
  store.daily_publish_success_log = store.daily_publish_success_log.slice(-300);
}
return { json: { ...j, publish_success_recorded: success } };

const first = $input.first();
const input = first && first.json && typeof first.json === 'object' ? first.json : {};
const body = input.body && typeof input.body === 'object' ? input.body : input;

const store = $getWorkflowStaticData('global');
store.daily_publish_queue = store.daily_publish_queue && typeof store.daily_publish_queue === 'object' ? store.daily_publish_queue : {};
store.daily_deleted_items = store.daily_deleted_items && typeof store.daily_deleted_items === 'object' ? store.daily_deleted_items : {};

const diagnosticItems = Array.isArray(body.phase3a_diagnostic_items) ? body.phase3a_diagnostic_items : [];
const diagnosticDeleted = body.phase3a_diagnostic_deleted_items && typeof body.phase3a_diagnostic_deleted_items === 'object'
  ? body.phase3a_diagnostic_deleted_items
  : {};
const useDiagnosticInput = diagnosticItems.length > 0;

const queue = useDiagnosticInput
  ? Object.fromEntries(diagnosticItems.map((item, idx) => [String(item.test_id || `diagnostic-${idx + 1}`), item]))
  : store.daily_publish_queue;
const deletedItems = useDiagnosticInput ? diagnosticDeleted : store.daily_deleted_items;

const nowSeoul = body.now_override
  ? new Date(String(body.now_override))
  : new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const todayKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;
const nowMinutes = nowSeoul.getHours() * 60 + nowSeoul.getMinutes();

function parseTimeMinutes(value) {
  const s = String(value || '').trim();
  const m = s.match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return null;
  const hh = Number(m[1]);
  const mm = Number(m[2]);
  if (!Number.isFinite(hh) || !Number.isFinite(mm) || hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
}

const summary = {
  mode: useDiagnosticInput ? 'diagnostic_input' : 'staticData',
  dry_run_only: true,
  now_kst: nowSeoul.toISOString(),
  today_key: todayKey,
  actual_static_queue_count: Object.keys(store.daily_publish_queue || {}).length,
  total_queue_count: 0,
  due_count: 0,
  would_publish_count: 0,
  would_publish_reels: 0,
  would_publish_carousels: 0,
  would_publish_feeds: 0,
  skipped_deleted_count: 0,
  skipped_pending_or_missing_count: 0,
  skipped_not_due_count: 0,
  skipped_already_done_count: 0,
  skipped_failed_or_blocked_count: 0,
  items: [],
};

for (const [testId, rawItem] of Object.entries(queue || {})) {
  const item = rawItem && typeof rawItem === 'object' ? rawItem : {};
  const postType = String(item.post_type || item.type || '').trim();
  const status = String(item.status || '').trim();
  const publishStatus = String(item.publish_status || '').trim().toLowerCase();
  const plannedTime = String(item.planned_publish_time || '').trim();
  const plannedMinutes = parseTimeMinutes(plannedTime);
  const isDeleted = status === 'deleted' || Boolean(deletedItems[testId]);

  const decision = {
    test_id: String(item.test_id || testId),
    post_type: postType,
    status,
    publish_status: publishStatus,
    planned_publish_time: plannedTime,
    decision: 'would_skip',
    would_skip_reason: '',
  };

  summary.total_queue_count += 1;

  if (isDeleted) {
    decision.would_skip_reason = 'deleted';
    summary.skipped_deleted_count += 1;
    summary.items.push(decision);
    continue;
  }

  if (status !== 'queued' || !postType || plannedMinutes === null) {
    decision.would_skip_reason = status !== 'queued' ? 'not_queued' : (!postType ? 'post_type_missing' : 'planned_publish_time_missing_or_invalid');
    summary.skipped_pending_or_missing_count += 1;
    summary.items.push(decision);
    continue;
  }

  if (publishStatus === 'published') {
    decision.would_skip_reason = 'already_published';
    summary.skipped_already_done_count += 1;
    summary.items.push(decision);
    continue;
  }

  if (publishStatus === 'failed' || publishStatus === 'blocked') {
    decision.would_skip_reason = `already_${publishStatus}`;
    summary.skipped_failed_or_blocked_count += 1;
    summary.items.push(decision);
    continue;
  }

  if (plannedMinutes > nowMinutes) {
    decision.would_skip_reason = 'not_due_yet';
    summary.skipped_not_due_count += 1;
    summary.items.push(decision);
    continue;
  }

  summary.due_count += 1;

  if (postType === 'reel') {
    if (!/^https?:\/\//i.test(String(item.video_url || ''))) {
      decision.would_skip_reason = 'reel_asset_missing';
      summary.skipped_pending_or_missing_count += 1;
    } else {
      decision.decision = 'would_publish';
      decision.would_skip_reason = '';
      summary.would_publish_count += 1;
      summary.would_publish_reels += 1;
    }
  } else if (postType === 'carousel') {
    const media = Array.isArray(item.carousel?.media) ? item.carousel.media : [];
    const hasPair = Boolean(item.paired_reel_test_id || item.paired_reel_slot || item.publish_after_reel_success);
    if (!hasPair) {
      decision.would_skip_reason = 'carousel_pairing_missing';
      summary.skipped_pending_or_missing_count += 1;
    } else if (media.length < 2 || media.length > 10) {
      decision.would_skip_reason = 'carousel_media_missing_or_invalid';
      summary.skipped_pending_or_missing_count += 1;
    } else {
      decision.decision = 'would_publish';
      decision.would_skip_reason = '';
      summary.would_publish_count += 1;
      summary.would_publish_carousels += 1;
    }
  } else if (postType === 'feed') {
    if (!String(item.caption || '').trim()) {
      decision.would_skip_reason = 'feed_caption_missing';
      summary.skipped_pending_or_missing_count += 1;
    } else if (!/^https?:\/\//i.test(String(item.image_url || item.media_url || ''))) {
      decision.would_skip_reason = 'feed_asset_missing';
      summary.skipped_pending_or_missing_count += 1;
    } else {
      decision.decision = 'would_publish';
      decision.would_skip_reason = '';
      summary.would_publish_count += 1;
      summary.would_publish_feeds += 1;
    }
  } else {
    decision.would_skip_reason = 'unknown_post_type';
    summary.skipped_pending_or_missing_count += 1;
  }

  summary.items.push(decision);
}

