const body = input.body && typeof input.body === 'object' ? input.body : input;
const store = $getWorkflowStaticData('global');
store.daily_publish_queue = store.daily_publish_queue && typeof store.daily_publish_queue === 'object' ? store.daily_publish_queue : {};
store.daily_deleted_items = store.daily_deleted_items && typeof store.daily_deleted_items === 'object' ? store.daily_deleted_items : {};
store.published_content_hashes = Array.isArray(store.published_content_hashes) ? store.published_content_hashes : [];

const nowSeoul = body.now_override ? new Date(String(body.now_override)) : new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const nowMinutes = nowSeoul.getHours() * 60 + nowSeoul.getMinutes();
const todayKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth()+1).padStart(2,'0')}-${String(nowSeoul.getDate()).padStart(2,'0')}`;

function parseTimeMinutes(value) {
  const s = String(value || '').trim();
  const m = s.match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return null;
  const hh = Number(m[1]);
  const mm = Number(m[2]);
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
}

function block(item, reason) {
  item.publish_status = 'blocked';
  item.blocked_reason = reason;
  item.blocked_at = new Date().toISOString();
  return { test_id: item.test_id, post_type: item.post_type, decision: 'blocked', reason };
}

function finalContentGuard(item) {
  if (item.duplicate_blocked === true) return 'content_duplicate_or_similar';
  if (item.needs_manual_review === true) return 'content_duplicate_or_similar';
  if (String(item.publish_status || '').toLowerCase() === 'published') return 'already_published';
  if (['failed','blocked'].includes(String(item.publish_status || '').toLowerCase())) return `already_${item.publish_status}`;
  const ch = String(item.content_hash || '').trim();
  if (ch && store.published_content_hashes.some(r => r.post_type === item.post_type && r.content_hash === ch && r.test_id !== item.test_id)) {
    return 'content_duplicate_or_similar';
  }
  return '';
}

async function publishFeed(item) {
  const imageUrl = String(item.image_url || item.media_url || '').trim();
  const caption = String(item.caption || '').trim();
  if (!imageUrl || !caption) throw new Error('missing_feed_asset');

  function getStatus(resp) {
    return Number(resp?.statusCode || resp?.status || 200);
  }
  function getBody(resp) {
    return resp && Object.prototype.hasOwnProperty.call(resp, 'body') ? resp.body : resp;
  }
  function throwGraph(stage, resp) {
    const status = getStatus(resp);
    const body = getBody(resp);
    const err = new Error(`${stage}_failed_${status}`);
    err.graphBody = body;
    err.httpStatus = status;
    throw err;
  }

  const createResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${GRAPH}/${IG_USER_ID}/media`,
    body: { image_url: imageUrl, caption, access_token: ACCESS_TOKEN },
    json: true,
    timeout: 60000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (getStatus(createResp) >= 400) throwGraph('feed_container_create', createResp);
  const create = getBody(createResp);
  const creationId = String(create?.id || '').trim();
  if (!creationId) throw new Error('feed_container_missing_id');
  await new Promise(resolve => setTimeout(resolve, 3000));

  const publishResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${GRAPH}/${IG_USER_ID}/media_publish`,
    body: { creation_id: creationId, access_token: ACCESS_TOKEN },
    json: true,
    timeout: 60000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (getStatus(publishResp) >= 400) throwGraph('feed_media_publish', publishResp);
  const published = getBody(publishResp);
  const mediaId = String(published?.id || '').trim();
  if (!mediaId) throw new Error('feed_publish_missing_media_id');
  return { media_id: mediaId, creation_id: creationId };
}
const summary = {
  dry_run: false,
  scheduler: 'phase3c',
  now_kst: nowSeoul.toISOString(),
  total_queue_count: Object.keys(store.daily_publish_queue).length,
  published: [],
  blocked: [],
  skipped: [],
  errors: [],
};

const entries = Object.entries(store.daily_publish_queue)
  .map(([key, item]) => [key, item && typeof item === 'object' ? item : {}])
  .sort((a,b) => String(a[1].planned_publish_time || '').localeCompare(String(b[1].planned_publish_time || '')));

for (const [key, item] of entries) {
  item.test_id = String(item.test_id || key);
  const status = String(item.status || '').toLowerCase();
  const postType = String(item.post_type || '').toLowerCase();
  const planned = parseTimeMinutes(item.planned_publish_time);
  if (store.daily_deleted_items[item.test_id] || status === 'deleted') {
    summary.skipped.push({ test_id: item.test_id, post_type: postType, reason: 'deleted' });
    continue;
  }
  if (status !== 'queued') {
    summary.skipped.push({ test_id: item.test_id, post_type: postType, reason: 'not_queued' });
    continue;
  }
  if (planned === null || planned > nowMinutes) {
    summary.skipped.push({ test_id: item.test_id, post_type: postType, reason: planned === null ? 'planned_publish_time_missing_or_invalid' : 'not_due_yet' });
    continue;
  }

  const guardReason = finalContentGuard(item);
  if (guardReason) {
    if (guardReason.startsWith('already_')) {
      summary.skipped.push({ test_id: item.test_id, post_type: postType, reason: guardReason });
    } else {
      summary.blocked.push(block(item, guardReason));
    }
    continue;
  }

  if (postType === 'carousel') {
    summary.blocked.push(block(item, 'carousel_rate_limit_pending'));
    continue;
  }

  try {
    if (postType === 'reel') {
      if (!/^https?:\/\//i.test(String(item.video_url || ''))) throw new Error('missing_reel_asset');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://n8n.mykindredai.com/webhook/clean_03_publisher',
        body: {
          caption: String(item.caption || ''),
          video_url: String(item.video_url || ''),
          test_id: item.test_id,
          approved_via: 'phase3c_scheduler',
          arm_live_publish: true,
          daily_publish_limit: Number(item.daily_publish_limit || store.daily_publish_limit || 3),
        },
        json: true,
        timeout: 120000,
      });
      item.publish_status = 'triggered';
      item.triggered_at = new Date().toISOString();
      item.publisher_workflow = 'clean_03_publisher';
      item.publisher_execution_confirmed = false;
      item.publisher_response = typeof res === 'object' ? res : { response: String(res || '') };
      summary.triggered = Array.isArray(summary.triggered) ? summary.triggered : [];
      summary.triggered.push({ test_id: item.test_id, post_type: postType, publisher: 'clean_03_publisher' });
    } else if (postType === 'feed') {
      const feed = await publishFeed.call(this, item);
      item.publish_status = 'published';
      item.published_at = new Date().toISOString();
      item.media_id = feed.media_id;
      item.creation_id = feed.creation_id;
      item.publisher_workflow = 'phase3c_feed_inline';
      summary.published.push({ test_id: item.test_id, post_type: postType, media_id: feed.media_id });
    } else {
      summary.blocked.push(block(item, 'unknown_post_type'));
      continue;
    }
    if (item.content_hash) {
      store.published_content_hashes.push({ test_id: item.test_id, post_type: postType, content_hash: item.content_hash, published_at: new Date().toISOString() });
      store.published_content_hashes = store.published_content_hashes.slice(-500);
    }
  } catch (e) {
    const response = e && e.response ? e.response : {};
    const rawCandidate = e.graphBody || response.body || response.data || e.body || e.data || e.description || (e.cause && (e.cause.body || e.cause.data || e.cause.message)) || '';
    let rawText = '';
    if (typeof rawCandidate === 'string') {
      rawText = rawCandidate;
    } else if (rawCandidate && typeof rawCandidate === 'object') {
      try { rawText = JSON.stringify(rawCandidate); } catch (_) { rawText = String(rawCandidate); }
    }
    if (!rawText) rawText = String(e.message || e || '');
    rawText = rawText.split(ACCESS_TOKEN).join('REDACTED');
    rawText = rawText.replace(/access_token=REDACTED&\\s]+)/gi, 'access_token=REDACTED');
    let responseBody = {};
    try { responseBody = JSON.parse(rawText); } catch (_) { responseBody = {}; }
    const graphError = responseBody && responseBody.error ? responseBody.error : {};
    item.publish_status = 'failed';
    item.failed_reason = String(e.message || e);
    item.failed_at = new Date().toISOString();
    item.graph_error_message = String(graphError.message || responseBody.message || rawText).slice(0, 1000);
    item.graph_error_code = graphError.code !== undefined ? graphError.code : '';
    item.graph_error_subcode = graphError.error_subcode !== undefined ? graphError.error_subcode : '';
    item.graph_error_type = String(graphError.type || '');
    item.graph_error_http_status = e.httpStatus || response.statusCode || response.status || '';
    item.graph_error_raw_sanitized = rawText.slice(0, 2000);
    item.graph_error_body_present = !!rawText;
    summary.errors.push({
      test_id: item.test_id,
      post_type: postType,
      error: item.failed_reason,
      graph_error_message: item.graph_error_message,
      graph_error_code: item.graph_error_code,
      graph_error_subcode: item.graph_error_subcode
    });
  }
}

